import Link from "next/link";
import SiteFooter from "../../components/SiteFooter";
import SiteHeader from "../../components/SiteHeader";

const roles = [
  ["Product & design", "Shape thoughtful tools for people preparing for their next big conversation."],
  ["Engineering", "Build fast, human-centered practice experiences with modern web technology."],
  ["Content & coaching", "Help turn expert insight into clear, useful preparation people can feel."],
];

export default function JobsPage() {
  return (
    <div className="mx-auto max-w-[1400px]">
      <SiteHeader />
      <main>
        <section className="border-b border-ink/15 py-16 sm:py-24 lg:py-32">
          <p className="mb-6 font-mono text-[10px] uppercase tracking-[0.13em] text-muted"><span className="mr-2 inline-block size-2 rounded-full bg-coral align-[1px]" /> Work with Ask Me</p>
          <h1 className="max-w-4xl font-display text-[clamp(3.5rem,9vw,8rem)] font-medium leading-[0.9] tracking-[-0.06em]">Make room for<br /><em className="text-coral">better work.</em></h1>
          <p className="mt-8 max-w-md text-[15px] leading-[1.65] text-muted">We are building a calmer, more capable way to prepare for the conversations that change careers.</p>
        </section>
        <section className="grid gap-10 py-14 sm:py-20 lg:grid-cols-[1.15fr_2fr]">
          <div><span className="font-mono text-[10px] text-coral">01</span><h2 className="mt-4 font-display text-4xl tracking-[-0.05em]">Open roles</h2></div>
          <div className="divide-y divide-ink/15 border-t border-ink/15">
            {roles.map(([title, description], index) => <article className="group grid gap-4 py-6 sm:grid-cols-[180px_1fr_auto] sm:items-center" key={title}><span className="font-mono text-[10px] text-coral">0{index + 1}</span><div><h3 className="font-display text-2xl tracking-[-0.04em]">{title}</h3><p className="mt-2 max-w-lg text-sm leading-relaxed text-muted">{description}</p></div><span className="text-xl text-coral transition-transform group-hover:translate-x-1" aria-hidden="true">↗</span></article>)}
          </div>
        </section>
        <section className="flex flex-wrap items-end justify-between gap-8 border-t border-ink/15 py-16 sm:py-24"><div><p className="mb-5 font-mono text-[10px] uppercase tracking-[0.13em] text-muted">No perfect fit?</p><h2 className="font-display text-5xl tracking-[-0.06em]">Start a<br /><em className="text-coral">conversation.</em></h2></div><Link className="bg-ink px-5 py-4 text-[13px] font-bold text-paper transition-transform hover:-translate-y-1" href="mailto:hello@askme.example">Say hello <span className="ml-3 text-base" aria-hidden="true">↗</span></Link></section>
      </main>
      <SiteFooter />
    </div>
  );
}
